--
-- Name: current_tenant_id(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.current_tenant_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    tenant_value text;
BEGIN

    tenant_value := current_setting(
        'app.current_tenant_id',
        true
    );

    IF tenant_value IS NULL
       OR btrim(tenant_value) = '' THEN
        RETURN NULL;
    END IF;

    BEGIN
        RETURN tenant_value::uuid;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RAISE EXCEPTION
                'Invalid app.current_tenant_id value: %',
                tenant_value;
    END;

END;
$$;


ALTER FUNCTION app.current_tenant_id() OWNER TO postgres;

--
-- Name: FUNCTION current_tenant_id(); Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON FUNCTION app.current_tenant_id() IS 'Returns the UUID of the currently active HMS tenant from app.current_tenant_id.';


--
-- Name: has_tenant_context(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.has_tenant_context() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT app.current_tenant_id() IS NOT NULL;
$$;


ALTER FUNCTION app.has_tenant_context() OWNER TO postgres;

--
-- Name: FUNCTION has_tenant_context(); Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON FUNCTION app.has_tenant_context() IS 'Returns TRUE when a valid tenant context is available for the current database session.';


--
-- Name: tenant_row_visible(uuid); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.tenant_row_visible(row_college_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT
        app.current_tenant_id() IS NOT NULL
        AND row_college_id = app.current_tenant_id();
$$;


ALTER FUNCTION app.tenant_row_visible(row_college_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION tenant_row_visible(row_college_id uuid); Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON FUNCTION app.tenant_row_visible(row_college_id uuid) IS 'Returns TRUE when a row belongs to the currently active HMS tenant.';


--
-- Name: validate_academic_tenant_consistency(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.validate_academic_tenant_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    referenced_college_id uuid;
BEGIN

    --------------------------------------------------------------------------
    -- PROGRAM -> DEPARTMENT
    --------------------------------------------------------------------------

    IF TG_TABLE_NAME = 'programs' THEN

        SELECT d.college_id
        INTO referenced_college_id
        FROM app.departments d
        WHERE d.department_id = NEW.department_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Department % does not exist',
                NEW.department_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant violation: program % and department % belong to different colleges',
                NEW.program_id,
                NEW.department_id;
        END IF;

    END IF;


    --------------------------------------------------------------------------
    -- COURSE -> DEPARTMENT / PROGRAM
    --------------------------------------------------------------------------

    IF TG_TABLE_NAME = 'courses' THEN

        SELECT d.college_id
        INTO referenced_college_id
        FROM app.departments d
        WHERE d.department_id = NEW.department_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Department % does not exist',
                NEW.department_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant violation: course % and department % belong to different colleges',
                NEW.course_id,
                NEW.department_id;
        END IF;


        IF NEW.program_id IS NOT NULL THEN

            SELECT p.college_id
            INTO referenced_college_id
            FROM app.programs p
            WHERE p.program_id = NEW.program_id;

            IF referenced_college_id IS NULL THEN
                RAISE EXCEPTION
                    'Program % does not exist',
                    NEW.program_id;
            END IF;

            IF referenced_college_id <> NEW.college_id THEN
                RAISE EXCEPTION
                    'Tenant violation: course % and program % belong to different colleges',
                    NEW.course_id,
                    NEW.program_id;
            END IF;

        END IF;

    END IF;


    --------------------------------------------------------------------------
    -- SEMESTER -> ACADEMIC YEAR
    --------------------------------------------------------------------------

    IF TG_TABLE_NAME = 'semesters' THEN

        SELECT ay.college_id
        INTO referenced_college_id
        FROM app.academic_years ay
        WHERE ay.academic_year_id = NEW.academic_year_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Academic year % does not exist',
                NEW.academic_year_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant violation: semester % and academic year % belong to different colleges',
                NEW.semester_id,
                NEW.academic_year_id;
        END IF;

    END IF;


    --------------------------------------------------------------------------
    -- BATCH -> PROGRAM / ACADEMIC YEAR
    --------------------------------------------------------------------------

    IF TG_TABLE_NAME = 'batches' THEN

        SELECT p.college_id
        INTO referenced_college_id
        FROM app.programs p
        WHERE p.program_id = NEW.program_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Program % does not exist',
                NEW.program_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant violation: batch % and program % belong to different colleges',
                NEW.batch_id,
                NEW.program_id;
        END IF;


        SELECT ay.college_id
        INTO referenced_college_id
        FROM app.academic_years ay
        WHERE ay.academic_year_id = NEW.academic_year_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Academic year % does not exist',
                NEW.academic_year_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant violation: batch % and academic year % belong to different colleges',
                NEW.batch_id,
                NEW.academic_year_id;
        END IF;

    END IF;


    RETURN NEW;

END;
$$;


