-- Name: FUNCTION validate_academic_tenant_consistency(); Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON FUNCTION app.validate_academic_tenant_consistency() IS 'Ensures related academic records always belong to the same college tenant.';


