--
-- Name: validate_communication_tenant_consistency(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.validate_communication_tenant_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    related_college_id uuid;
BEGIN
    IF TG_TABLE_NAME = 'notifications' THEN
        IF NEW.college_id IS NOT NULL THEN
            IF NOT EXISTS (SELECT 1 FROM platform.colleges WHERE college_id = NEW.college_id) THEN
                RAISE EXCEPTION 'Invalid college_id in notifications';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'notification_recipients' THEN
        SELECT college_id INTO related_college_id FROM app.notifications WHERE id = NEW.notification_id;
        IF related_college_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM platform.user_roles ur WHERE ur.user_id = NEW.user_id AND ur.college_id = related_college_id
            ) THEN
                RAISE EXCEPTION 'Notification recipient belongs to a different college';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'announcements' THEN
        IF NOT EXISTS (SELECT 1 FROM platform.colleges WHERE college_id = NEW.college_id) THEN
            RAISE EXCEPTION 'Invalid college_id in announcements';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION app.validate_communication_tenant_consistency() OWNER TO postgres;

--
-- Name: validate_hostel_tenant_consistency(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.validate_hostel_tenant_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    referenced_college_id uuid;
BEGIN

    IF TG_TABLE_NAME = 'blocks' THEN
        SELECT h.college_id INTO referenced_college_id FROM app.hostels h WHERE h.id = NEW.hostel_id;
        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION 'Hostel % does not exist', NEW.hostel_id;
        END IF;
        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION 'Tenant violation: block % and hostel % belong to different colleges', NEW.id, NEW.hostel_id;
        END IF;
    END IF;

    IF TG_TABLE_NAME = 'floors' THEN
        SELECT b.college_id INTO referenced_college_id FROM app.blocks b WHERE b.id = NEW.block_id;
        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION 'Block % does not exist', NEW.block_id;
        END IF;
        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION 'Tenant violation: floor % and block % belong to different colleges', NEW.id, NEW.block_id;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM app.hostels h WHERE h.id = NEW.hostel_id AND h.college_id = NEW.college_id) THEN
            RAISE EXCEPTION 'Invalid hostel % for floor %', NEW.hostel_id, NEW.id;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM app.blocks b WHERE b.id = NEW.block_id AND b.hostel_id = NEW.hostel_id AND b.college_id = NEW.college_id) THEN
            RAISE EXCEPTION 'Floor % hierarchy does not match its block/hostel', NEW.id;
        END IF;
    END IF;

    IF TG_TABLE_NAME = 'rooms' THEN
        SELECT f.college_id INTO referenced_college_id FROM app.floors f WHERE f.id = NEW.floor_id;
        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION 'Floor % does not exist', NEW.floor_id;
        END IF;
        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION 'Tenant violation: room % and floor % belong to different colleges', NEW.id, NEW.floor_id;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM app.floors f WHERE f.id = NEW.floor_id AND f.hostel_id = NEW.hostel_id AND f.block_id = NEW.block_id AND f.college_id = NEW.college_id) THEN
            RAISE EXCEPTION 'Room % hierarchy does not match its floor/block/hostel', NEW.id;
        END IF;
    END IF;

    IF TG_TABLE_NAME = 'beds' THEN
        SELECT r.college_id INTO referenced_college_id FROM app.rooms r WHERE r.id = NEW.room_id;
        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION 'Room % does not exist', NEW.room_id;
        END IF;
        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION 'Tenant violation: bed % and room % belong to different colleges', NEW.id, NEW.room_id;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM app.rooms r WHERE r.id = NEW.room_id AND r.hostel_id = NEW.hostel_id AND r.block_id = NEW.block_id AND r.floor_id = NEW.floor_id AND r.college_id = NEW.college_id) THEN
            RAISE EXCEPTION 'Bed % hierarchy does not match its room/floor/block/hostel', NEW.id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION app.validate_hostel_tenant_consistency() OWNER TO postgres;

--
-- Name: validate_meals_resources_tenant_consistency(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.validate_meals_resources_tenant_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    related_college_id uuid;
BEGIN

    -- ========================================================
    -- MEAL MENUS
    -- ========================================================

    IF TG_TABLE_NAME = 'meal_menus' THEN

        SELECT college_id
        INTO related_college_id
        FROM app.hostels
        WHERE id = NEW.hostel_id;

        IF related_college_id IS NULL
           OR related_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant mismatch in meal_menus';
        END IF;

    -- ========================================================
    -- MEAL TIMINGS
    -- ========================================================

    ELSIF TG_TABLE_NAME = 'meal_timings' THEN

        SELECT college_id
        INTO related_college_id
        FROM app.hostels
        WHERE id = NEW.hostel_id;

        IF related_college_id IS NULL
           OR related_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant mismatch in meal_timings';
        END IF;

    -- ========================================================
    -- MESS NOTICES
    -- ========================================================

    ELSIF TG_TABLE_NAME = 'mess_notices' THEN

        SELECT college_id
        INTO related_college_id
        FROM app.hostels
        WHERE id = NEW.hostel_id;

        IF related_college_id IS NULL
           OR related_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant mismatch in mess_notices';
        END IF;

    -- ========================================================
    -- FOOD FEEDBACK
    -- ========================================================

    ELSIF TG_TABLE_NAME = 'food_feedback' THEN

        SELECT college_id
        INTO related_college_id
        FROM app.students
        WHERE id = NEW.student_id;

        IF related_college_id IS NULL
           OR related_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant mismatch in food_feedback student';
        END IF;

        SELECT college_id
        INTO related_college_id
        FROM app.meal_menus
        WHERE id = NEW.menu_id;

        IF related_college_id IS NULL
           OR related_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant mismatch in food_feedback menu';
        END IF;

    -- ========================================================
    -- RESOURCE ITEMS
    -- ========================================================

    ELSIF TG_TABLE_NAME = 'resource_items' THEN

        SELECT college_id
        INTO related_college_id
        FROM app.hostels
        WHERE id = NEW.hostel_id;

        IF related_college_id IS NULL
           OR related_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant mismatch in resource_items';
        END IF;

    -- ========================================================
    -- RESOURCE AVAILABILITY
    -- ========================================================

    ELSIF TG_TABLE_NAME = 'resource_availability' THEN

        SELECT college_id
        INTO related_college_id
        FROM app.resource_items
        WHERE id = NEW.resource_id;

        IF related_college_id IS NULL
           OR related_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Tenant mismatch in resource_availability';
        END IF;

    -- ========================================================
    -- SAVED REPORTS
    -- ========================================================

    ELSIF TG_TABLE_NAME = 'reports_saved' THEN

        IF NOT EXISTS (
            SELECT 1
            FROM platform.colleges
            WHERE college_id = NEW.college_id
        ) THEN
            RAISE EXCEPTION
                'Invalid college_id in reports_saved';
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM app.users
            WHERE user_id = NEW.owner_user_id
              AND college_id = NEW.college_id
        ) THEN
            RAISE EXCEPTION
                'Report owner belongs to a different college';
        END IF;

    -- ========================================================
    -- FILES
    -- ========================================================

    ELSIF TG_TABLE_NAME = 'files' THEN

        /*
         * Files may be global/platform-level when college_id
         * is NULL. College-owned files must reference a valid
         * college.
         */
        IF NEW.college_id IS NOT NULL THEN

            IF NOT EXISTS (
                SELECT 1
                FROM platform.colleges
                WHERE college_id = NEW.college_id
            ) THEN
                RAISE EXCEPTION
                    'Invalid college_id in files';
            END IF;

        END IF;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION app.validate_meals_resources_tenant_consistency() OWNER TO postgres;

--
-- Name: validate_movement_tenant_consistency(); Type: FUNCTION; Schema: app; Owner: postgres
--

CREATE FUNCTION app.validate_movement_tenant_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    referenced_college_id uuid;
BEGIN

    -- ========================================================
    -- ATTENDANCE CARD
    -- ========================================================

    IF TG_TABLE_NAME = 'attendance_cards' THEN

        SELECT college_id
        INTO referenced_college_id
        FROM app.students
        WHERE id = NEW.student_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Student % does not exist',
                NEW.student_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Student % and attendance card belong to different colleges',
                NEW.student_id;
        END IF;

    END IF;


    -- ========================================================
    -- ATTENDANCE RECORD
    -- ========================================================

    IF TG_TABLE_NAME = 'attendance_records' THEN

        SELECT college_id
        INTO referenced_college_id
        FROM app.students
        WHERE id = NEW.student_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Student % does not exist',
                NEW.student_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Student % and attendance record belong to different colleges',
                NEW.student_id;
        END IF;


        IF NEW.card_id IS NOT NULL THEN

            SELECT college_id
            INTO referenced_college_id
            FROM app.attendance_cards
            WHERE id = NEW.card_id;

            IF referenced_college_id IS NULL THEN
                RAISE EXCEPTION
                    'Attendance card % does not exist',
                    NEW.card_id;
            END IF;

            IF referenced_college_id <> NEW.college_id THEN
                RAISE EXCEPTION
                    'Attendance card % and attendance record belong to different colleges',
                    NEW.card_id;
            END IF;

        END IF;

    END IF;


    -- ========================================================
    -- ENTRY / EXIT
    -- ========================================================

    IF TG_TABLE_NAME = 'entry_exit_records' THEN

        SELECT college_id
        INTO referenced_college_id
        FROM app.students
        WHERE id = NEW.student_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Student % does not exist',
                NEW.student_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Student % and movement record belong to different colleges',
                NEW.student_id;
        END IF;


        IF NEW.card_id IS NOT NULL THEN

            SELECT college_id
            INTO referenced_college_id
            FROM app.attendance_cards
            WHERE id = NEW.card_id;

            IF referenced_college_id IS NULL THEN
                RAISE EXCEPTION
                    'Attendance card % does not exist',
                    NEW.card_id;
            END IF;

            IF referenced_college_id <> NEW.college_id THEN
                RAISE EXCEPTION
                    'Attendance card % and movement record belong to different colleges',
                    NEW.card_id;
            END IF;

        END IF;


        SELECT college_id
        INTO referenced_college_id
        FROM app.gates
        WHERE id = NEW.gate_id;

        IF referenced_college_id IS NULL THEN
            RAISE EXCEPTION
                'Gate % does not exist',
                NEW.gate_id;
        END IF;

        IF referenced_college_id <> NEW.college_id THEN
            RAISE EXCEPTION
                'Gate % and movement record belong to different colleges',
                NEW.gate_id;
        END IF;

    END IF;


    RETURN NEW;
END;
$$;


