CREATE FUNCTION platform.prevent_audit_log_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    RAISE EXCEPTION
        'Audit logs are immutable and cannot be updated or deleted';

END;
$$;


ALTER FUNCTION platform.prevent_audit_log_mutation() OWNER TO postgres;

--
-- Name: validate_approval_segregation(); Type: FUNCTION; Schema: platform; Owner: postgres
--

CREATE FUNCTION platform.validate_approval_segregation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    requester_id uuid;
BEGIN

    SELECT requested_by
    INTO requester_id
    FROM platform.approval_requests
    WHERE request_id = NEW.request_id;

    IF requester_id IS NOT NULL
       AND NEW.approver_id = requester_id THEN

        RAISE EXCEPTION
            'Maker-checker violation: requester cannot approve their own request';

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.validate_approval_segregation() OWNER TO postgres;

--
-- Name: validate_college_lifecycle(); Type: FUNCTION; Schema: platform; Owner: postgres
--

CREATE FUNCTION platform.validate_college_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- Activated timestamp cannot be after suspension.
    IF NEW.activated_at IS NOT NULL
       AND NEW.suspended_at IS NOT NULL
       AND NEW.activated_at > NEW.suspended_at THEN

        RAISE EXCEPTION
            'College activated_at cannot be later than suspended_at';

    END IF;


    -- Suspension cannot occur after deactivation.
    IF NEW.suspended_at IS NOT NULL
       AND NEW.deactivated_at IS NOT NULL
       AND NEW.suspended_at > NEW.deactivated_at THEN

        RAISE EXCEPTION
            'College suspended_at cannot be later than deactivated_at';

    END IF;


    -- Deactivation cannot occur after archival.
    IF NEW.deactivated_at IS NOT NULL
       AND NEW.archived_at IS NOT NULL
       AND NEW.deactivated_at > NEW.archived_at THEN

        RAISE EXCEPTION
            'College deactivated_at cannot be later than archived_at';

    END IF;


    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.validate_college_lifecycle() OWNER TO postgres;

--
-- Name: validate_module_hierarchy(); Type: FUNCTION; Schema: platform; Owner: postgres
--

CREATE FUNCTION platform.validate_module_hierarchy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_parent_kind varchar(20);
BEGIN
    IF NEW.parent_id IS NULL THEN
        IF NEW.kind <> 'APP' THEN
            RAISE EXCEPTION
                'Root module must have kind APP';
        END IF;

        RETURN NEW;
    END IF;

    SELECT kind
    INTO v_parent_kind
    FROM platform.modules
    WHERE module_id = NEW.parent_id;

    IF NEW.kind = 'MODULE'
       AND v_parent_kind <> 'APP' THEN
        RAISE EXCEPTION
            'MODULE parent must be APP';
    END IF;

    IF NEW.kind = 'FEATURE'
       AND v_parent_kind <> 'MODULE' THEN
        RAISE EXCEPTION
            'FEATURE parent must be MODULE';
    END IF;

    IF NEW.kind = 'APP' THEN
        RAISE EXCEPTION
            'APP cannot have a parent';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.validate_module_hierarchy() OWNER TO postgres;

--
-- Name: validate_support_access_dates(); Type: FUNCTION; Schema: platform; Owner: postgres
--

CREATE FUNCTION platform.validate_support_access_dates() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    IF NEW.revoked_at IS NOT NULL
       AND NEW.approved_at IS NOT NULL
       AND NEW.revoked_at < NEW.approved_at THEN

        RAISE EXCEPTION
            'Support access revoked_at cannot be earlier than approved_at';

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.validate_support_access_dates() OWNER TO postgres;

--
-- Name: validate_user_role_scope(); Type: FUNCTION; Schema: platform; Owner: postgres
--

CREATE FUNCTION platform.validate_user_role_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_scope varchar(20);
BEGIN
    SELECT scope
    INTO v_scope
    FROM platform.roles
    WHERE role_id = NEW.role_id;

    IF v_scope = 'COLLEGE' AND NEW.college_id IS NULL THEN
        RAISE EXCEPTION
            'COLLEGE role assignment requires college_id';
    END IF;

    IF v_scope = 'PLATFORM' AND NEW.college_id IS NOT NULL THEN
        RAISE EXCEPTION
            'PLATFORM role assignment must not have college_id';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.validate_user_role_scope() OWNER TO postgres;

