--
-- Name: v_active_sos_alerts; Type: VIEW; Schema: app; Owner: postgres
--

CREATE VIEW app.v_active_sos_alerts AS
 SELECT s.id AS sos_alert_id,
    s.college_id,
    s.student_id,
    st.admission_number,
    st.registration_number,
    st.roll_number,
    st.first_name,
    st.middle_name,
    st.last_name,
    s.alert_number,
    s.alert_type,
    s.message,
    s.latitude,
    s.longitude,
    s.location_description,
    s.status,
    s.triggered_at,
    s.acknowledged_by,
    s.acknowledged_at,
    s.resolved_by,
    s.resolved_at,
    s.resolution_notes,
    s.created_at,
    s.updated_at
   FROM (app.sos_alerts s
     LEFT JOIN app.students st ON (((st.id = s.student_id) AND (st.college_id = s.college_id))))
  WHERE ((s.status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'TRIGGERED'::character varying, 'ACKNOWLEDGED'::character varying])::text[]));


ALTER VIEW app.v_active_sos_alerts OWNER TO postgres;

