-- Name: VIEW v_active_sos_alerts; Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON VIEW app.v_active_sos_alerts IS 'Currently active, triggered, or acknowledged SOS alerts.';


--
-- Name: v_current_student_bed_allocation; Type: VIEW; Schema: app; Owner: postgres
--

CREATE VIEW app.v_current_student_bed_allocation AS
 SELECT ba.id AS allocation_id,
    ba.college_id,
    ba.student_id,
    s.admission_number,
    s.registration_number,
    s.roll_number,
    s.first_name,
    s.middle_name,
    s.last_name,
    h.id AS hostel_id,
    h.code AS hostel_code,
    h.name AS hostel_name,
    b.id AS block_id,
    b.code AS block_code,
    b.name AS block_name,
    f.id AS floor_id,
    f.code AS floor_code,
    f.name AS floor_name,
    f.floor_number,
    r.id AS room_id,
    r.code AS room_code,
    r.name AS room_name,
    r.room_type,
    be.id AS bed_id,
    be.code AS bed_code,
    be.name AS bed_name,
    ba.allocation_type,
    ba.allocated_at,
    ba.released_at,
    ba.status,
    ba.remarks,
    ba.created_at,
    ba.updated_at
   FROM ((((((app.bed_allocations ba
     JOIN app.students s ON (((s.id = ba.student_id) AND (s.college_id = ba.college_id))))
     JOIN app.beds be ON (((be.id = ba.bed_id) AND (be.college_id = ba.college_id))))
     LEFT JOIN app.rooms r ON (((r.id = be.room_id) AND (r.college_id = ba.college_id))))
     LEFT JOIN app.floors f ON (((f.id = be.floor_id) AND (f.college_id = ba.college_id))))
     LEFT JOIN app.blocks b ON (((b.id = be.block_id) AND (b.college_id = ba.college_id))))
     LEFT JOIN app.hostels h ON (((h.id = be.hostel_id) AND (h.college_id = ba.college_id))))
  WHERE (ba.status = 'ACTIVE'::text);


ALTER VIEW app.v_current_student_bed_allocation OWNER TO postgres;

--
-- Name: VIEW v_current_student_bed_allocation; Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON VIEW app.v_current_student_bed_allocation IS 'Current active bed allocation and complete hostel location hierarchy for students.';


