    CONSTRAINT chk_visitor_checkout CHECK (((check_out_at IS NULL) OR (check_in_at IS NULL) OR (check_out_at >= check_in_at))),
    CONSTRAINT visitor_visits_status_check CHECK (((status)::text = ANY ((ARRAY['EXPECTED'::character varying, 'CHECKED_IN'::character varying, 'CHECKED_OUT'::character varying, 'CANCELLED'::character varying, 'DENIED'::character varying, 'EXPIRED'::character varying])::text[])))
