--
-- Name: v_current_visitor_activity; Type: VIEW; Schema: app; Owner: postgres
--

CREATE VIEW app.v_current_visitor_activity AS
 SELECT vv.id AS visitor_visit_id,
    vv.college_id,
    vv.student_id,
    s.admission_number,
    s.registration_number,
    s.roll_number,
    s.first_name,
    s.middle_name,
    s.last_name,
    v.id AS visitor_id,
    v.full_name AS visitor_name,
    v.phone AS visitor_phone,
    v.email AS visitor_email,
    vv.purpose,
    vv.gate_id,
    vv.check_in_at,
    vv.check_out_at,
    vv.status,
    vv.verified_by,
    vv.remarks,
    vv.created_at,
    vv.updated_at
   FROM ((app.visitor_visits vv
     JOIN app.visitors v ON (((v.id = vv.visitor_id) AND (v.college_id = vv.college_id))))
     LEFT JOIN app.students s ON (((s.id = vv.student_id) AND (s.college_id = vv.college_id))))
  WHERE ((vv.status)::text = ANY ((ARRAY['EXPECTED'::character varying, 'CHECKED_IN'::character varying])::text[]));


ALTER VIEW app.v_current_visitor_activity OWNER TO postgres;

--
-- Name: VIEW v_current_visitor_activity; Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON VIEW app.v_current_visitor_activity IS 'Visitors currently expected or checked into the hostel/campus.';


--
-- Name: v_hostel_occupancy; Type: VIEW; Schema: app; Owner: postgres
--

CREATE VIEW app.v_hostel_occupancy AS
 SELECT h.id AS hostel_id,
    h.college_id,
    h.code AS hostel_code,
    h.name AS hostel_name,
    h.category,
    h.total_capacity,
    count(
        CASE
            WHEN (ba.status = 'ACTIVE'::text) THEN ba.id
            ELSE NULL::uuid
        END) AS occupied_beds,
    GREATEST((h.total_capacity - count(
        CASE
            WHEN (ba.status = 'ACTIVE'::text) THEN ba.id
            ELSE NULL::uuid
        END)), (0)::bigint) AS available_capacity,
        CASE
            WHEN (h.total_capacity > 0) THEN round((((count(
            CASE
                WHEN (ba.status = 'ACTIVE'::text) THEN ba.id
                ELSE NULL::uuid
            END))::numeric / (h.total_capacity)::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS occupancy_percentage,
    h.status,
    h.created_at,
    h.updated_at
   FROM ((app.hostels h
     LEFT JOIN app.beds be ON (((be.hostel_id = h.id) AND (be.college_id = h.college_id))))
     LEFT JOIN app.bed_allocations ba ON (((ba.bed_id = be.id) AND (ba.college_id = h.college_id) AND (ba.status = 'ACTIVE'::text))))
  GROUP BY h.id, h.college_id, h.code, h.name, h.category, h.total_capacity, h.status, h.created_at, h.updated_at;


ALTER VIEW app.v_hostel_occupancy OWNER TO postgres;

--
-- Name: VIEW v_hostel_occupancy; Type: COMMENT; Schema: app; Owner: postgres
--

COMMENT ON VIEW app.v_hostel_occupancy IS 'Hostel capacity, occupied beds, available capacity, and occupancy percentage.';


--
-- Name: v_open_complaint_summary; Type: VIEW; Schema: app; Owner: postgres
--

CREATE VIEW app.v_open_complaint_summary AS
 SELECT college_id,
    category,
    priority,
    status,
    count(*) AS complaint_count,
    min(created_at) AS oldest_complaint_at,
    max(created_at) AS latest_complaint_at
   FROM app.complaints c
  WHERE ((status)::text <> ALL ((ARRAY['CLOSED'::character varying, 'RESOLVED'::character varying])::text[]))
  GROUP BY college_id, category, priority, status;


