CREATE VIEW app.v_pending_leave_requests AS
 SELECT lr.id AS leave_request_id,
    lr.college_id,
    lr.student_id,
    s.admission_number,
    s.registration_number,
    s.roll_number,
    s.first_name,
    s.middle_name,
    s.last_name,
    lr.leave_type,
    lr.reason,
    lr.from_date,
    lr.to_date,
    lr.from_time,
    lr.to_time,
    lr.destination,
    lr.contact_phone,
    lr.status,
    lr.requested_at,
    lr.created_by,
    lr.updated_by,
    lr.created_at,
    lr.updated_at
   FROM (app.leave_requests lr
     JOIN app.students s ON (((s.id = lr.student_id) AND (s.college_id = lr.college_id))))
  WHERE ((lr.status)::text = ANY ((ARRAY['PENDING'::character varying, 'PARENT_APPROVED'::character varying])::text[]));


ALTER VIEW app.v_pending_leave_requests OWNER TO postgres;

