--

CREATE VIEW app.v_resource_availability AS
 SELECT ri.id AS resource_id,
    ri.college_id,
    ri.hostel_id,
    ri.resource_type,
    ri.name,
    ri.description,
    ri.total_qty,
    ri.unit,
    ra.available_qty,
    ra.status AS availability_status,
    ra.updated_by,
    ra.updated_at AS availability_updated_at,
    ri.status AS resource_status,
    ri.created_at,
    ri.updated_at
   FROM (app.resource_items ri
     LEFT JOIN app.resource_availability ra ON (((ra.resource_id = ri.id) AND (ra.college_id = ri.college_id))))
  WHERE ((ri.status)::text = 'ACTIVE'::text);


