--
-- Name: v_student_current_location; Type: VIEW; Schema: app; Owner: postgres
--

CREATE VIEW app.v_student_current_location AS
 SELECT s.id AS student_id,
    s.college_id,
    s.admission_number,
    s.registration_number,
    s.roll_number,
    s.first_name,
    s.middle_name,
    s.last_name,
    latest.movement_type,
    latest.recorded_at,
    latest.gate_id,
    latest.verification_method,
    latest.recorded_by,
    latest.remarks
   FROM (app.students s
     LEFT JOIN LATERAL ( SELECT eer.movement_type,
            eer.recorded_at,
            eer.gate_id,
            eer.verification_method,
            eer.recorded_by,
            eer.remarks
           FROM app.entry_exit_records eer
          WHERE ((eer.student_id = s.id) AND (eer.college_id = s.college_id))
          ORDER BY eer.recorded_at DESC
         LIMIT 1) latest ON (true));


ALTER VIEW app.v_student_current_location OWNER TO postgres;

