--
-- Name: user_roles; Type: TABLE; Schema: platform; Owner: postgres
--

CREATE TABLE platform.user_roles (
    user_role_id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    role_id uuid NOT NULL,
    college_id uuid,
    status character varying(30) DEFAULT 'ACTIVE'::character varying NOT NULL,
    assigned_by uuid,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_user_roles_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'SUSPENDED'::character varying, 'REVOKED'::character varying, 'EXPIRED'::character varying])::text[])))
);


ALTER TABLE platform.user_roles OWNER TO postgres;

--
-- Name: TABLE user_roles; Type: COMMENT; Schema: platform; Owner: postgres
--

COMMENT ON TABLE platform.user_roles IS 'Associates users with roles and, for college roles, a specific college tenant.';


